import{z as E,x as c,o as i,c as p,q as r,j as l,D as o,d as t,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"指令选择","description":"","frontmatter":{"title":"指令选择","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/instruction-select.md","filePath":"cs/instruction-select.md","lastUpdated":1791413859000}'),B={name:"cs/instruction-select.md"};function A(h,a,u,m,C,D){const d=c("Mermaid");return i(),p("div",null,[a[2]||(a[2]=r('<h1 id="指令选择" tabindex="-1">指令选择 <a class="header-anchor" href="#指令选择" aria-label="Permalink to &quot;指令选择&quot;">​</a></h1><div class="epigraph"><p>把 IR 运算树（或 DAG）盖上目标机的指令模板；同一树可以有多种覆盖，代价不同。</p><footer>—— 据龙书第 8 章；Aho, Ganapathi and Tjiang, Code Generation Using Tree Matching, 1989 整理</footer></div><p>上一课<a href="/cs/available-expr">可用表达式</a>仍在虚拟名上。本课不着色。缺口是：三地址的 <code>+</code>、<code>load</code> 要变成<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>或另一 ISA 的具体 opcode。选择可以局部树匹配，也可以 tiling。寄存器还当无限，名字仍是虚拟的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IR 是目标无关的。<code>t3 &lt;- t1 + t2</code> 在 RISC-V 是 <code>add</code>，在 CISC 可能是带访存的一条。缺口是模板：树模式 \\(\\leftrightarrow\\) 指令 + 代价。最大吞或动态规划选最小代价覆盖。本课用树模式直觉，不写完整 BURG 生成器。</p><p><span class="marginnote">直觉类比：指令选择像拿一套现成的贴纸去盖一棵运算树——每张贴纸是一个指令模板，可以只盖一个节点，也可以连枝带叶盖住一小撮；盖法不止一种，目标是找出总代价最小的完整覆盖。</span></p><p>组成课已有指令格式与寄存器堆；本课只问「哪条指令实现这个 IR 节点」。调用序列的参数寄存器留给 ABI。</p><h3 id="选择不是分配" tabindex="-1">选择不是分配 <a class="header-anchor" href="#选择不是分配" aria-label="Permalink to &quot;选择不是分配&quot;">​</a></h3><p>选出 <code>add rd, rs1, rs2</code> 仍带虚拟寄存器。分配把虚拟映到 <code>x10</code> 或溢出。顺序通常先选后分配，或二者交错；主干先选。窥孔还可以在选完后改写。</p><p><span class="marginnote">常见误区：初学者容易以为这一步结束寄存器就叫 <code>x10</code> 之类的真名了；此时输出的仍是 <code>t3</code> 这类虚拟名，要等寄存器分配才落位。另外选错模板通常只是多几条指令、慢一点，并不会改变语义。</span></p><p><span class="marginnote">龙书 8.9 节树重写。Aho–Ganapathi–Tjiang 的树匹配。RISC 上选择往往接近 1:1，CISC 上 tiling 收益大。本课两边都承认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把基本块内 IR 看成森林/DAG。对每个根，用动态规划或贪婪匹配盖模板。访存指令带宽度，来自类型课的 size。非法组合（未对齐）按 ABI 与 ISA 拒绝或拆成多条。</p>',13)),(i(),l(s,null,{default:o(()=>[n(d,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IR%5B%22IR%20%E6%A0%91%20%2F%20DAG%22%5D%20--%3E%20PAT%5B%22ISA%20%E6%A8%A1%E6%9D%BF%22%5D%0A%20%20PAT%20--%3E%20TILE%5B%22%E8%A6%86%E7%9B%96%22%5D%0A%20%20TILE%20--%3E%20MI%5B%22%E6%9C%BA%E5%99%A8%E6%8C%87%E4%BB%A4%20%2B%20%E8%99%9A%E6%8B%9F%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/instruction-format"},"指令格式"),t("决定立即数能否塞进一条；放不下则先 "),e("code",null,"lui"),t("/"),e("code",null,"addi"),t(" 一类，仍是选择。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"代价：周期或长度。错误选择会多指令，不一定错语义。副作用（标志位）在 CISC 上要进模板。RISC-V 整数子集本课够用；浮点、向量不在本课。",-1)),a[6]||(a[6]=e("p",null,"一个具体问题：立即数放不进单条模板时，选择阶段怎么拆。",-1)),(i(),l(s,null,{default:o(()=>[n(d,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22IR%EF%BC%9At3%20%E2%86%90%20t1%20%2B%20100000%22%5D%20--%3E%20P1%5B%22%E6%A8%A1%E6%9D%BF%20A%EF%BC%9Aaddi%20rd%2C%20rs1%2C%20imm%22%5D%0A%20%20P1%20--%3E%20C1%7B%2212%20%E4%BD%8D%E7%AB%8B%E5%8D%B3%E6%95%B0%E6%94%BE%E5%BE%97%E4%B8%8B%E5%90%97%22%7D%0A%20%20C1%20--%3E%7C%22%E6%94%BE%E4%B8%8D%E4%B8%8B%22%7C%20P2%5B%22%E6%A8%A1%E6%9D%BF%20B%EF%BC%9Alui%20%E9%AB%98%2020%20%E4%BD%8D%20%2B%20addi%20%E4%BD%8E%2012%20%E4%BD%8D%22%5D%0A%20%20P2%20--%3E%20OUT%5B%22%E4%B8%A4%E6%9D%A1%E6%8C%87%E4%BB%A4%EF%BC%8C%E7%BB%93%E6%9E%9C%E4%BB%8D%E5%8F%AB%20t3%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：RISC-V 的 I 型立即数只有 12 位，能表达 -2048 到 2047。要给 <code>t1</code> 加 100000，一条 <code>addi</code> 装不下，选择阶段就得换成 <code>lui</code> 装高 20 位、<code>addi</code> 补低 12 位的组合模板。</span></p><p>与超标量、流水线课：选择可以避开已知冒险对，但不代替分配与调度。本课不排流水线调度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不填着色、不写调用惯例细节、不做全局指令调度。窥孔是更窄窗口的本地改写，后两课才到。后课默认：虚拟寄存器机器指令已选出。冲突图着色把虚拟收成物理寄存器或溢出。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指令选择 = ISA 模板覆盖 IR；代价可选优。</li><li>输出仍含虚拟寄存器。</li><li>RISC 近 1:1；复杂 ISA 才显 tiling。</li><li>出处：Aho et al., 龙书第 8 章；Aho, Ganapathi and Tjiang, 1989。</li></ul>',6))])}const S=E(B,[["render",A]]);export{f as __pageData,S as default};
